={{ JSON.stringify((() => {
  const s = $('Start trace').first().json;
  const failed = $('Read failed').isExecuted;
  const out = (failed ? $('Read failed') : $('Decode thread')).first().json;
  const startNs = String(DateTime.fromISO(s.trace_start).toMillis()) + '000000';
  const endNs = String($now.toMillis()) + '000000';
  const str = (k, v) => ({ key: k, value: { stringValue: String(v == null ? '' : v) } });
  const nested = !!s.parent_span_id;
  const attrs = [
    str('langfuse.observation.type', 'tool'),
    str('langfuse.observation.input', JSON.stringify({ thread_id: s.thread_id })),
    str('langfuse.observation.output', failed ? out.error : JSON.stringify({ thread_id: out.thread_id, message_count: (out.messages || []).length, chars: (out.messages || []).reduce((n, m) => n + (m.body || '').length, 0) })),
    str('langfuse.observation.level', failed ? 'ERROR' : 'DEFAULT'),
    str('langfuse.observation.status_message', failed ? out.error : ''),
    str('langfuse.observation.metadata.workflow_id', $workflow.id),
    str('langfuse.observation.metadata.execution_id', $execution.id),
    str('langfuse.observation.metadata.message_count', (out.messages || []).length)
  ];
  if (!nested) {
    attrs.push(str('langfuse.trace.name', 'cm-read-thread'));
    attrs.push({ key: 'langfuse.trace.tags', value: { arrayValue: { values: [{ stringValue: 'n8n' }, { stringValue: 'cm-read-thread' }] } } });
    attrs.push(str('langfuse.trace.metadata.workflow_name', $workflow.name));
    attrs.push(str('langfuse.trace.metadata.mode', $execution.mode));
  }
  if (s.user_id) attrs.push(str('langfuse.user.id', s.user_id));
  const span = {
    traceId: s.trace_id, spanId: s.span_id, name: 'read_thread', kind: 1,
    startTimeUnixNano: startNs, endTimeUnixNano: endNs,
    attributes: attrs,
    status: { code: failed ? 2 : 1 }
  };
  if (nested) span.parentSpanId = s.parent_span_id;
  return { resourceSpans: [{
    resource: { attributes: [str('service.name', 'n8n')] },
    scopeSpans: [{ scope: { name: 'n8n-cm-read-thread' }, spans: [span] }]
  }] };
})()) }}

